"""PDF parser, on PDFs generated by the tests with reportlab.

The layout is deliberately different from the real corpus (Helvetica, other
sizes, dash bullets, another header text): the parser must not rely on the
look of one corpus.
"""

from pathlib import Path

import pytest
from app.rag.parsers import get_parser
from app.rag.parsers.base import ParsingError
from app.rag.parsers.models import DocumentMetadata
from app.rag.parsers.pdf_parser import PdfParser

reportlab = pytest.importorskip("reportlab")  # in the optional "corpus" group

from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import ParagraphStyle
from reportlab.pdfgen import canvas
from reportlab.platypus import PageBreak, Paragraph, SimpleDocTemplate, Spacer, Table

DOCUMENT = DocumentMetadata(
    document_id="T-003",
    version_id="T-003-v1.0",
    family_id="test",
    title="Test",
    doc_type="policy",
    version="1.0",
    lifecycle_status="active",
    effective_from="2026-01-01",
    language="fr",
    category="test",
    department_scope="all",
    owner="test",
)

TITLE = ParagraphStyle("title", fontName="Helvetica-Bold", fontSize=22, leading=28, spaceAfter=12)
H1 = ParagraphStyle("h1", fontName="Helvetica-Bold", fontSize=16, leading=20, spaceBefore=14, spaceAfter=8)
H2 = ParagraphStyle("h2", fontName="Helvetica-Bold", fontSize=13, leading=17, spaceBefore=10, spaceAfter=6)
H3_SAME_SIZE = ParagraphStyle("h3", fontName="Helvetica-Bold", fontSize=11, leading=15, spaceBefore=8)
BODY = ParagraphStyle("body", fontName="Helvetica", fontSize=11, leading=15, spaceAfter=9)
NOTE = ParagraphStyle("note", fontName="Helvetica-Oblique", fontSize=10, leading=13, spaceAfter=9)
LONG = (
    "Cette règle de test s'applique à toutes les équipes et elle est volontairement assez longue "
    "pour occuper plusieurs lignes dans la page, afin de vérifier que les lignes sont bien regroupées "
    "en un seul paragraphe par le parser, quelle que soit la police utilisée."
)


def running_text(pdf_canvas, doc) -> None:
    pdf_canvas.setFont("Helvetica", 8)
    pdf_canvas.drawString(50, A4[1] - 30, "Société Exemple — Confidentiel")
    pdf_canvas.drawString(50, 25, f"Page {doc.page}")


def build_pdf(tmp_path: Path, story: list, header: bool = True) -> Path:
    path = tmp_path / "doc.pdf"
    doc = SimpleDocTemplate(str(path), pagesize=A4, topMargin=90, bottomMargin=90)
    if header:
        doc.build(story, onFirstPage=running_text, onLaterPages=running_text)
    else:
        doc.build(story)
    return path


def table(rows: list[list[str]], bold_header: bool = True) -> Table:
    style = [("GRID", (0, 0), (-1, -1), 0.5, colors.black), ("FONTSIZE", (0, 0), (-1, -1), 10)]
    if bold_header:
        style.append(("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"))
    return Table(rows, style=style)


def parse(path: Path, **options: object):
    return PdfParser(**options).parse(path, DOCUMENT, "doc.pdf")


@pytest.fixture
def policy_pdf(tmp_path: Path) -> Path:
    story = [
        Paragraph("Politique d'exemple", TITLE),
        Paragraph("Avertissement : ceci est un document d'exemple.", NOTE),
        Paragraph("1. Champ d'application", H1),
        Paragraph(LONG, BODY),
        Paragraph("1.1 Personnes concernées", H2),
        Paragraph("Les personnes suivantes sont concernées :", BODY),
        Paragraph("- les salariés en contrat permanent ;", BODY),
        Paragraph("- les salariés en contrat temporaire.", BODY),
        PageBreak(),
        Paragraph("2. Délais", H1),
        Paragraph("Les délais sont les suivants.", BODY),
        table([["Durée", "Délai minimum"], ["1 jour", "3 jours"], ["5 jours", "10 jours"]]),
        Spacer(1, 12),
        Paragraph("2.1 Cas particulier", H3_SAME_SIZE),
        Paragraph("Un délai réduit est possible avec accord.", BODY),
        Paragraph("1 le responsable valide ;", BODY),
        Paragraph("2 l'équipe RH confirme.", BODY),
        PageBreak(),
        Paragraph("3. Contacts", H1),
        Paragraph("Écrire à l'équipe dédiée.", BODY),
    ]
    return build_pdf(tmp_path, story)


def test_registered_for_pdf() -> None:
    assert isinstance(get_parser(".pdf"), PdfParser)


def test_running_headers_and_footers_are_removed(policy_pdf: Path) -> None:
    texts = " ".join(e.text for e in parse(policy_pdf).elements)

    assert "Confidentiel" not in texts
    assert "Page" not in texts


def test_headings_levels_follow_font_sizes(policy_pdf: Path) -> None:
    headings = [(e.text, e.level) for e in parse(policy_pdf).elements if e.type == "heading"]

    assert headings == [
        ("Politique d'exemple", 1),
        ("1. Champ d'application", 2),
        ("1.1 Personnes concernées", 3),
        ("2. Délais", 2),
        ("2.1 Cas particulier", 4),  # bold + numbered at body size: smallest heading size
        ("3. Contacts", 2),
    ]


def test_lines_of_a_paragraph_are_joined(policy_pdf: Path) -> None:
    paragraph = next(e for e in parse(policy_pdf).elements if e.text.startswith("Cette règle"))

    assert paragraph.type == "paragraph"
    assert paragraph.text == LONG
    assert paragraph.page == 1
    assert paragraph.section_path == ["Politique d'exemple", "1. Champ d'application"]
    assert paragraph.section_number == "1"


def test_list_items(policy_pdf: Path) -> None:
    items = [e.text for e in parse(policy_pdf).elements if e.type == "list_item"]

    assert items == [
        "- les salariés en contrat permanent ;",
        "- les salariés en contrat temporaire.",
        "1 le responsable valide ;",
        "2 l'équipe RH confirme.",
    ]


def test_table_is_extracted_once_with_its_header(policy_pdf: Path) -> None:
    elements = parse(policy_pdf).elements
    table_element = next(e for e in elements if e.type == "table")

    assert table_element.data == {
        "header": ["Durée", "Délai minimum"],
        "rows": [["1 jour", "3 jours"], ["5 jours", "10 jours"]],
    }
    assert table_element.page == 2
    assert table_element.section_number == "2"
    assert not any("Délai minimum" in e.text for e in elements if e.type != "table")
    # the table sits between the paragraph that announces it and the next heading
    position = elements.index(table_element)
    assert elements[position - 1].text == "Les délais sont les suivants."
    assert elements[position + 1].text == "2.1 Cas particulier"


def test_disclaimer_comes_from_options(policy_pdf: Path) -> None:
    def kind(parsed):
        return next(e.type for e in parsed.elements if e.text.startswith("Avertissement"))

    assert kind(parse(policy_pdf)) == "paragraph"
    assert kind(parse(policy_pdf, disclaimer_patterns=[r"document d'exemple"])) == "disclaimer"


def test_parsing_is_deterministic(policy_pdf: Path) -> None:
    assert parse(policy_pdf).to_json() == parse(policy_pdf).to_json()


def test_paragraph_cut_by_a_page_break_is_joined(tmp_path: Path) -> None:
    path = tmp_path / "doc.pdf"
    pdf = canvas.Canvas(str(path), pagesize=A4)
    pdf.setFont("Helvetica", 11)
    pdf.drawString(60, 700, "Une phrase qui commence en bas de la première page et qui")
    pdf.showPage()
    pdf.setFont("Helvetica", 11)
    pdf.drawString(60, 760, "se termine en haut de la page suivante.")
    pdf.drawString(60, 720, "Une autre phrase.")
    pdf.save()

    elements = parse(path).elements

    assert [e.text for e in elements] == [
        (
            "Une phrase qui commence en bas de la première page et qui "
            "se termine en haut de la page suivante."
        ),
        "Une autre phrase.",
    ]
    assert elements[0].page == 1


def test_table_cut_by_a_page_break_is_joined(tmp_path: Path) -> None:
    rows = [["Version", "Changement"]] + [[f"1.{n}", f"Changement numéro {n}"] for n in range(45)]
    story = [Paragraph("Historique", H1), Table(rows, repeatRows=1, style=[
        ("GRID", (0, 0), (-1, -1), 0.5, colors.black),
        ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"),
    ])]
    elements = parse(build_pdf(tmp_path, story, header=False)).elements
    tables = [e for e in elements if e.type == "table"]

    assert len(tables) == 1
    assert tables[0].data["header"] == ["Version", "Changement"]
    assert len(tables[0].data["rows"]) == 45


def test_pdf_without_text_layer_needs_ocr(tmp_path: Path) -> None:
    path = tmp_path / "scan.pdf"
    pdf = canvas.Canvas(str(path), pagesize=A4)
    pdf.rect(50, 50, 400, 600, fill=1)  # an "image" of a page, no text
    pdf.save()

    with pytest.raises(ParsingError, match="OCR"):
        parse(path)


def test_single_page_keeps_its_margin_text(tmp_path: Path) -> None:
    # With one page nothing can be "repeated", so nothing is dropped.
    path = build_pdf(tmp_path, [Paragraph("Seul paragraphe.", BODY)])

    texts = [e.text for e in parse(path).elements]

    assert "Seul paragraphe." in texts
    assert any("Confidentiel" in text for text in texts)

